import pytest
from unittest.mock import Mock

# Assuming the retry function is defined in the module under test
# from your_module import retry

# For completeness, the function:
def retry(fn, max_attempts: int = 3):
    for attempt in range(max_attempts):
        try:
            return fn()
        except Exception:
            if attempt == max_attempts - 1:
                raise


# ------------------------------------------------------------
# Happy path
# ------------------------------------------------------------
def test_success_on_first_attempt():
    fn = Mock(return_value="ok")
    result = retry(fn, max_attempts=3)
    assert result == "ok"
    assert fn.call_count == 1


def test_success_after_failures():
    fn = Mock(side_effect=[ValueError, ValueError, "ok"])
    result = retry(fn, max_attempts=3)
    assert result == "ok"
    assert fn.call_count == 3


def test_success_with_custom_max_attempts():
    # 4 failures, then success -> max_attempts=5
    fn = Mock(side_effect=[ValueError, ValueError, ValueError, ValueError, "ok"])
    result = retry(fn, max_attempts=5)
    assert result == "ok"
    assert fn.call_count == 5


# ------------------------------------------------------------
# Error cases (exhausted attempts)
# ------------------------------------------------------------
def test_raises_after_max_attempts():
    fn = Mock(side_effect=ValueError("boom"))
    with pytest.raises(ValueError, match="boom"):
        retry(fn, max_attempts=3)
    assert fn.call_count == 3


def test_raises_immediately_when_max_attempts_1_and_fails():
    fn = Mock(side_effect=ValueError("fail"))
    with pytest.raises(ValueError, match="fail"):
        retry(fn, max_attempts=1)
    assert fn.call_count == 1


def test_retry_with_non_callable_raises_after_max_attempts():
    # A non-callable (e.g., None) will raise TypeError on every call,
    # and retry should exhaust all attempts before re-raising.
    # We can't easily assert call count with None, but we can with a Mock
    # raising the same TypeError.
    fn = Mock(side_effect=TypeError("not callable"))
    with pytest.raises(TypeError, match="not callable"):
        retry(fn, max_attempts=3)
    assert fn.call_count == 3


# ------------------------------------------------------------
# Edge cases
# ------------------------------------------------------------
def test_max_attempts_zero():
    fn = Mock()
    result = retry(fn, max_attempts=0)
    assert result is None
    fn.assert_not_called()


def test_max_attempts_negative():
    fn = Mock()
    result = retry(fn, max_attempts=-5)
    assert result is None
    fn.assert_not_called()


def test_max_attempts_one_success():
    fn = Mock(return_value="ok")
    result = retry(fn, max_attempts=1)
    assert result == "ok"
    assert fn.call_count == 1


def test_uncaught_base_exception_propagates_immediately():
    # KeyboardInterrupt / SystemExit are NOT subclasses of Exception,
    # so they should bypass the retry logic entirely.
    fn = Mock(side_effect=KeyboardInterrupt)
    with pytest.raises(KeyboardInterrupt):
        retry(fn, max_attempts=3)
    assert fn.call_count == 1  # no retry


def test_invalid_max_attempts_type_string_raises_typeerror():
    with pytest.raises(TypeError, match="integer"):
        retry(Mock(), max_attempts="3")


def test_invalid_max_attempts_type_float_raises_typeerror():
    with pytest.raises(TypeError):
        retry(Mock(), max_attempts=1.5)
